let rules = [ValidationRule::parse("decimal_required", "")?, ValidationRule::parse("decimal_gt", "0")?];
let errors = validate_decimal("amount{1}", &Decimal::default(), &rules);
let value = serde_json::json!({"errors": errors.iter().map(|e| serde_json::json!({"field":e.field,"tag":e.tag,"parameter":e.parameter})).collect::<Vec<_>>(), "messages": ValidationMessages::new("zh-Hans").translate(&errors)});

